public static class UnifiedChecks {
    static T Field<T>(object value,string name){return (T)value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    static void Set(object value,string name,object data){value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(value,data);}
    static object Call(object value,string name,params object[] args){MethodInfo method=value.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic);int missing=method.GetParameters().Length-args.Length;if(missing>0)args=args.Concat(Enumerable.Repeat<object>(Type.Missing,missing)).ToArray();return method.Invoke(value,args);}
    static System.Collections.Generic.IEnumerable<Control> All(Control root){yield return root;foreach(Control child in root.Controls)foreach(Control item in All(child))yield return item;}
    [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr handle);
    [DllImport("user32.dll")]static extern bool ShowWindow(IntPtr handle,int command);
    [DllImport("user32.dll")]static extern bool AttachThreadInput(uint from,uint to,bool attach);
    [DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();
    [DllImport("user32.dll")]static extern bool PostMessage(IntPtr handle,uint message,IntPtr w,IntPtr l);
    static void Activate(Form form,TextBox field){uint pid;uint foreground=Native.GetWindowThreadProcessId(Native.GetForegroundWindow(),out pid),current=GetCurrentThreadId();bool attached=false;try{if(current!=foreground)attached=AttachThreadInput(current,foreground,true);ShowWindow(form.Handle,5);form.Activate();SetForegroundWindow(form.Handle);field.Focus();}finally{if(attached)AttachThreadInput(current,foreground,false);}}
    static async Task Wait(Func<bool> ready){DateTime start=DateTime.UtcNow;while(!ready()){if((DateTime.UtcNow-start).TotalSeconds>30)throw new Exception("Unified fixture timed out");await Task.Delay(40);}}
    static async Task<DictationSession> Selected(FlowContext context,Form form,TextBox field,string source,string command){Activate(form,field);field.Text="Before. "+source+" After.";field.Select(8,source.Length);await Wait(()=>Native.GetForegroundWindow()==form.Handle&&Native.FocusedHandle(form.Handle)==field.Handle);await Task.Delay(100);FocusTarget target=FocusTarget.Capture();string selected=target.CaptureSelection();if(selected!=source)throw new Exception("Fixture selection was not exposed: target window="+target.Window+" expected="+form.Handle+" current="+Native.GetForegroundWindow()+" target control="+target.Control+" expected="+field.Handle+" current="+Native.FocusedHandle(Native.GetForegroundWindow())+" matches="+target.MatchesCurrent()+" selected length="+(selected==null?-1:selected.Length));DictationSession current=new DictationSession {Target=target,SelectedText=selected,Style="Keep my wording",Rewrite=true};current.Pending.Add(Task.FromResult(command));Set(context,"session",current);Call(context,"Finish",current);await Wait(()=>Field<DictationSession>(context,"session")==null);return current;}
    static void Render(Form form,string path){using(Bitmap image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
    public static async Task Run(FlowContext context,Form form,TextBox first,TextBox second,Action<bool,string> check,string output) {
        uint mods,key;check(Hotkey.Parse("Ctrl + Alt + R",out mods,out key)&&mods==0x4003&&key==0x52,"Custom shortcut parses arbitrary modifier and key combinations");check(Hotkey.Parse("F12",out mods,out key)&&key==0x7B&&!Hotkey.Parse("A",out mods,out key)&&!Hotkey.Parse("Ctrl + Escape",out mods,out key),"Shortcut accepts function keys and rejects typing keys or Escape");
        using(ShortcutPicker picker=new ShortcutPicker("Ctrl + Shift + Space")){form.Controls.Add(picker);picker.PerformClick();Message message=new Message();object[] args={message,Keys.Control|Keys.Alt|Keys.R};typeof(ShortcutPicker).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(picker,args);check(picker.Value=="Ctrl + Alt + R"&&!picker.Capturing&&!ShortcutWindow.Capturing,"Shortcut picker records pressed keys and exits capture");picker.PerformClick();args=new object[]{message,Keys.Escape};typeof(ShortcutPicker).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(picker,args);check(picker.Value=="Ctrl + Alt + R"&&!picker.Capturing,"Escape cancels shortcut capture without changing its value");picker.PerformClick();typeof(ShortcutPicker).GetMethod("OnMouseDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(picker,new object[]{new MouseEventArgs(MouseButtons.XButton2,1,20,20,0)});check(picker.Value=="Mouse 5"&&!picker.Capturing,"Shortcut picker accepts mouse side buttons");form.Controls.Remove(picker);}
        using(ShortcutWindow shortcut=new ShortcutWindow()){check(shortcut.Register("Ctrl + Alt + R")&&shortcut.Label=="Ctrl + Alt + R","Native global shortcut registers the recorded combination");check(shortcut.Register("Mouse 5")&&shortcut.Label=="Mouse 5","Mouse shortcut does not register an unrelated keyboard shortcut");}
        check(SpokenAction.Parse("Please translate this into French.","English").Language=="French"&&SpokenAction.Parse("translate this to Spanish and keep the bullets", "English").Action=="Translate","Spoken translation chooses its requested language");check(SpokenAction.Parse("Can you summarize this in three bullets?","English").Action=="Summarize"&&SpokenAction.Parse("give me a brief summary", "English").ShowsCard,"Spoken summaries route to the result card");check(!SpokenAction.Parse("Rewrite this like a friendly email", "English").ShowsCard&&SpokenAction.Parse("Change Saturday to Sunday", "English").Action=="Rewrite","Spoken edits route to selection replacement");check(SpokenAction.Parse("Rewrite this and keep the word translate", "English").Action=="Rewrite","Action words inside an edit do not misroute it");
        Utterances audio=new Utterances();byte[] voice=new byte[9600];for(int i=0;i<voice.Length;i+=2){short sample=(short)(4000*Math.Sin(i*.06));voice[i]=(byte)sample;voice[i+1]=(byte)(sample>>8);}audio.Push(voice);audio.Push(new byte[32000]);bool heard;double duration,silence;audio.Activity(out heard,out duration,out silence);check(heard&&silence==1&&!RecordingModes.ShouldStop("Automatic",duration,heard,silence),"Automatic recording allows a short pause after speech");audio.Push(new byte[16000]);audio.Activity(out heard,out duration,out silence);check(RecordingModes.ShouldStop("Automatic",duration,heard,silence)&&!RecordingModes.ShouldStop("Hold to talk",duration,heard,silence)&&!RecordingModes.ShouldStop("Click to start / stop",duration,heard,silence),"Automatic recording stops after silence while other modes wait for input");check(RecordingModes.ShouldStop("Automatic",10,false,10)&&!RecordingModes.ShouldStop("Automatic",9,false,9),"Automatic recording closes an empty recording after ten seconds");
        check(ModelLibrary.SpeechModels.Length==2&&ModelLibrary.TextModels.Length==6,"Catalog offers two speech and six language models");check(ModelLibrary.SpeechModels.Concat(ModelLibrary.TextModels).All(f=>f.Sha256.Length==64&&f.Revision.Length==40&&f.Bytes>0),"Every offered model has a pinned revision size and hash");foreach(ModelFile speech in ModelLibrary.SpeechModels)foreach(ModelFile text in ModelLibrary.TextModels)check(ModelLibrary.Find(speech.Name,text.Name)!=null,"Independent combination accepted: "+speech.Name+" + "+text.Name);
        Settings settings=Field<Settings>(context,"settings");string root=Field<string>(context,"root");
        using(ModelWindow models=new ModelWindow(root,settings,new ComputerSpecs {RamBytes=128L*1073741824,GpuBytes=12L*1073741824})){models.Show();ComboBox speech=All(models).OfType<ComboBox>().Single(c=>c.Name=="Speech-to-text"),text=All(models).OfType<ComboBox>().Single(c=>c.Name=="Language model");object originalText=text.SelectedItem;speech.SelectedIndex=1;check(text.SelectedItem==originalText,"Changing speech model preserves language selection");text.SelectedIndex=5;check(speech.SelectedIndex==1,"Changing language model preserves speech selection");Render(models,Path.Combine(output,"independent-models-preview.png"));models.Close();}
        using(SettingsWindow preferences=new SettingsWindow(settings,new[]{"Ctrl + Shift + Space"})){preferences.Show();preferences.SelectSection("Shortcuts");check(All(preferences).OfType<ShortcutPicker>().Count()==1&&!All(preferences).OfType<Label>().Any(l=>l.Text=="AI tools"||l.Text.StartsWith("Voice edit:")),"Shortcuts has one recorder and no separate AI shortcut");ChoiceCard automatic=All(preferences).OfType<ChoiceCard>().Single(c=>c.Text=="Automatic");automatic.Checked=true;Settings saved=null;preferences.Saved=value=>saved=value;All(preferences).OfType<Button>().Single(b=>b.Text=="Save shortcut").PerformClick();check(saved!=null&&saved.RecordingMode=="Automatic","Recording mode saves through the settings page");check(!All(preferences).OfType<Label>().Any(l=>l.Text.Contains("Applies to every app")),"Style has no applies-to-every-app text");Render(preferences,Path.Combine(output,"unified-shortcut-preview.png"));preferences.Close();}
        HistoryStore history=Field<HistoryStore>(context,"history");Pill pill=Field<Pill>(context,"pill");bool showBar=settings.ShowBar,notifications=settings.WindowsNotifications;settings.ShowBar=false;settings.WindowsNotifications=false;pill.Persistent=false;
        try {
            string source="The meeting is on Saturday. Bring the blue folder.";DictationSession rewritten=await Selected(context,form,first,source,"Change Saturday to Sunday and blue to green.");if(first.Text!="Before. The meeting is on Sunday. Bring the green folder. After.")Console.WriteLine("Selected rewrite diagnostic: field="+first.Text+" result="+(history.Snapshot().FirstOrDefault()==null?"empty":history.Snapshot().First().Result)+" action="+rewritten.ActionName+" matches="+rewritten.Target.MatchesCurrent()+" current="+Native.GetForegroundWindow()+" expected="+form.Handle+" notice="+Field<NotifyIcon>(context,"tray").BalloonTipText);check(first.Text=="Before. The meeting is on Sunday. Bring the green folder. After."&&rewritten.ActionName=="Rewrite","Unified spoken rewrite replaces only the selected text");
            string translationSource="Hello Sarah. The meeting is Friday at 2 PM. Bring the blue folder.";await Selected(context,form,first,translationSource,"Translate this into French.");check(first.Text=="Before. "+translationSource+" After."&&pill.ResultReady&&pill.Caption.Contains("Translation")&&pill.ResultText.Contains("Sarah")&&pill.ResultText.ToLowerInvariant().Contains("vendredi"),"Spoken translation leaves source intact and shows translated result");check(All(pill).OfType<TextBox>().Single(t=>t.Name=="Card result").Visible&&!Field<System.Windows.Forms.Timer>(pill,"dismiss").Enabled,"Translation has a full scrollable persistent result card");Render(pill,Path.Combine(output,"translation-card-preview.png"));Rectangle copy=(Rectangle)typeof(Pill).GetProperty("CopyBounds",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pill,null);int pos=((copy.Top+12)<<16)|(copy.Left+20);PostMessage(pill.Handle,0x201,new IntPtr(1),new IntPtr(pos));PostMessage(pill.Handle,0x202,IntPtr.Zero,new IntPtr(pos));await Task.Delay(100);check(Clipboard.GetText()==pill.ResultText,"Translation card copies its full result");
            string summarySource="The launch is Friday at 2 PM. Sarah will bring the blue folder. We must test the app before launch. The review is Thursday.";await Selected(context,form,first,summarySource,"Summarize this in two bullets.");check(first.Text=="Before. "+summarySource+" After."&&pill.Caption=="Summary"&&pill.ResultText.Contains("Friday")&&pill.ResultText.Contains("Sarah"),"Spoken summary appears on the card without replacing source text");Render(pill,Path.Combine(output,"summary-card-preview.png"));await history.FlushAsync();check(history.Snapshot().Any(e=>e.Mode=="Summarize"&&e.Transcript.Contains("two bullets"))&&history.Snapshot().Any(e=>e.Mode=="Translate to French"),"History retains spoken commands and result types");
            string faqSource="All right, question one. is what color is the sky. The answer is blue. Question two is what color is the ocean? The answer is also blue. Yeah.";await Selected(context,form,first,faqSource,"rewrite this");string pastedFaq=first.Text.Replace("\r\n","\n");Console.WriteLine("FAQ paste fixture: "+pastedFaq.Replace("\n"," | "));check(pastedFaq.Contains("sky?\nBlue")&&pastedFaq.Contains("ocean?\nBlue")&&!pastedFaq.Contains("question one")&&pastedFaq.StartsWith("Before. ")&&pastedFaq.EndsWith(" After."),"Spoken rewrite this formats an FAQ and pastes the selected replacement");Activate(form,first);first.Select(first.TextLength,0);await Wait(()=>Native.GetForegroundWindow()==form.Handle);await Task.Delay(100);FocusTarget heldTarget=FocusTarget.Capture();heldTarget.CaptureSelection();DictationSession held=new DictationSession {Target=heldTarget,Rewrite=false,Style="Original transcript"};held.Pending.Add(Task.FromResult("Held recording result."));Set(context,"session",held);Set(context,"keyboardHeld",held);Call(context,"KeyboardRelease");await Wait(()=>Field<DictationSession>(context,"session")==null);if(!held.Stopped||!first.Text.Contains("Held recording result."))Console.WriteLine("Held diagnostic: stopped="+held.Stopped+" text="+first.Text.Replace("\n"," | ")+" target="+held.Target.Window+" current="+Native.GetForegroundWindow()+" field="+held.Target.Control+" currentField="+Native.FocusedHandle(Native.GetForegroundWindow())+" matches="+held.Target.MatchesCurrent()+" selectionMatches="+held.Target.SelectionMatches()+" modifiers="+Native.ModifiersDown()+" notice="+Field<NotifyIcon>(context,"tray").BalloonTipText);check(held.Stopped&&first.Text.Contains("Held recording result."),"Releasing the held shortcut finishes and pastes recording");
            Activate(form,second);second.Text="";await Wait(()=>Native.GetForegroundWindow()==form.Handle&&Native.FocusedHandle(form.Handle)==second.Handle);await Task.Delay(100);DictationSession automaticSession=new DictationSession {Target=FocusTarget.Capture(),RecordingMode="Automatic",Style="Original transcript",Rewrite=false};automaticSession.Segments.Push(voice);automaticSession.Segments.Push(new byte[64000]);automaticSession.Pending.Add(Task.FromResult("Automatic recording result."));Set(context,"session",automaticSession);await Wait(()=>Field<DictationSession>(context,"session")==null);if(!automaticSession.Stopped||second.Text!="Automatic recording result.")Console.WriteLine("Automatic fixture: stopped="+automaticSession.Stopped+" text="+second.Text+" target="+automaticSession.Target.Window+" foreground="+Native.GetForegroundWindow()+" notice="+Field<NotifyIcon>(context,"tray").BalloonTipText);check(automaticSession.Stopped&&second.Text=="Automatic recording result.","Automatic recording finishes through the live UI timer");
            Activate(form,second);DictationSession empty=new DictationSession {Target=FocusTarget.Capture(),Rewrite=false,Style="Original transcript"};Set(context,"session",empty);Call(context,"Finish",empty);await Wait(()=>Field<DictationSession>(context,"session")==null);check(pill.Caption=="No speech detected"&&!settings.WindowsNotifications,"Empty recording gives inline feedback with Windows notifications disabled");
            settings.WindowsNotifications=true;Call(context,"Notify","Synthetic important notice");DateTime stamp=Field<DateTime>(context,"lastNotification");Call(context,"Notify","Another synthetic notice");check(Field<DateTime>(context,"lastNotification")==stamp,"Enabled Windows notifications are limited to one per minute");
            settings.WindowsNotifications=false;pill.ShowIdle();PostMessage(pill.Handle,0x201,new IntPtr(1),new IntPtr((19<<16)|166));PostMessage(pill.Handle,0x202,IntPtr.Zero,new IntPtr((19<<16)|166));await Task.Delay(100);HubWindow hub=Field<HubWindow>(context,"hub");check(hub!=null&&Field<Form>(hub,"page") is DashboardWindow,"Floating bar Open app opens Home");hub.Close();
        }finally{settings.ShowBar=showBar;settings.WindowsNotifications=notifications;pill.Persistent=showBar;pill.Conceal();history.Clear();Field<UsageStore>(context,"usage").Clear();first.Text="";second.Text="";} await history.FlushAsync();await Field<UsageStore>(context,"usage").FlushAsync();
    }
}
